#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 1;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        // Convert to camel case
        char buffer[1024];
        while (fgets(buffer, 1024, stdin)) {
            char *p = buffer;
            while (*p) {
                if (*p == '_') {
                    p++;
                    if (*p) {
                        *p = toupper(*p);
                    }
                }
                p++;
            }
            printf("%s", buffer);
        }
    } else if (strcmp(argv[1], "to_snake") == 0) {
        // Convert to snake case
        char buffer[1024];
        while (fgets(buffer, 1024, stdin)) {
            char *p = buffer;
            while (*p) {
                if (isupper(*p)) {
                    printf("_%c", tolower(*p));
                } else {
                    printf("%c", *p);
                }
                p++;
            }
            printf("\n");
        }
    } else {
        printf("INVALID_MODE\n");
        return 1;
    }
    return 0;
}
